--
-- Name: FilteredAsinResultsView; Type: VIEW; Schema: public; Owner: viasuser
--

CREATE VIEW public."FilteredAsinResultsView" AS
 SELECT m.name AS manufacturer,
    b.name AS brand,
    public.get_asin_filter_reason(a.id) AS "filterReason",
    (count(a.id))::integer AS "asinCount",
    string_agg(a.code, ', '::text) AS asins
   FROM ((public."ASIN" a
     JOIN public."Brand" b ON ((a."brandId" = b.id)))
     JOIN public."Manufacturer" m ON ((a."manufacturerId" = m.id)))
  GROUP BY m.name, b.name, (public.get_asin_filter_reason(a.id))
  ORDER BY (public.get_asin_filter_reason(a.id)) NULLS FIRST, (count(a.id)) DESC;


ALTER VIEW public."FilteredAsinResultsView" OWNER TO viasuser;

